var a=[{title:`Vad låg belastning betyder`,text:`Rörelser med låg belastning håller oftast minst en fot i marken, eller använder utrustning som en motionscykel för att ta bort stötarna mot marken. Låg belastning kan ändå vara hög intensitet och kan fortfarande belasta lederna. Ett hårt cykelintervall kan pressa hjärta och lungor, och vissa stegövningar kräver fortfarande mycket av knän och höfter.`},{title:`Bra rörelseval`,text:`Rask promenad, marsch, sidosteg med tåtryck, skuggboxning utan studsande, kontrollerade uppsteg, cykling och crosstrainers är alla praktiska alternativ. I ett litet rum kan du växla mellan rask marsch och medvetna sidosteg eller lätta slag. Välj rörelser som känns stabila och lägg inte till snabba vridningar bara för att göra det svårare.`},{title:`Exempel`,text:`Efter en gradvis uppvärmning, upprepa 45 sekunders rask marsch och 45 sekunders lugn promenad sex gånger. Bestäm ditt eget tempo och din egen vila. Kopiera inte någon annans fart. För att gå vidare, förläng de aktiva perioderna eller hela passet innan du går efter explosiv fart.`},{title:`Anpassa efter varför du undviker stötar`,text:`Om problemet är buller kan det räcka att släppa hoppen. Om ett knä, en fotled eller en rygg är känslig kan även vanligt gående göra ont, och du kan behöva träffa en läkare eller fysioterapeut. Träning med låg belastning är ingen behandling och garanterar inte smärtlindring.`},{title:`Så använder du TrainUp`,text:`I Profil anger du om hopp är okej, hur mycket buller som är okej, ditt underlag, din nivå, din utrustning och eventuella begränsningar per kroppsdel. Programmet använder alla tillsammans, och när hopp är avstängt utelämnar det hopprep och andra hoppövningar. Marsch eller cykling kan hålla uppe ansträngningen i deras ställe. Skatta passets ansträngning efteråt som vanligt.`}];var n=[{label:`CDC: rekommendationer om fysisk aktivitet för vuxna`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: mäta aktivitetsintensitet och pratprovet`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var r={sections:a,sources:n};export{r as default,a as sections,n as sources};